package nativeui

import (
	"fmt"
	"strconv"
	"strings"

	"github.com/egoist/mygo/ui"
)

// tokenState is the Token page's state.
type tokenState struct {
	// Create form.
	name     string
	symbol   string
	supply   string
	decimals float64
	owner    string
	// ownerPriv is the private half of a key pair generated by the Create card.
	// It is shown once for copying and never stored by the service.
	ownerPriv string
	// ownerKeyTokenID is the token created with ownerPriv. The write forms can
	// reuse that key only while this token is the subject; selecting another
	// token hides the button rather than signing for the wrong owner.
	ownerKeyTokenID string

	// Read forms.
	tokenID string
	// resolvedOwner is the owner already confirmed for resolvedOwnerID by a
	// list selection, token creation or TokenInfo read. Kept separately from
	// the visible page so paging does not erase the subject's owner context.
	resolvedOwner   string
	resolvedOwnerID string
	// subjectID is the token id whose owner context has been applied to the
	// write forms. A manual edit to Token ID can bypass the row-selection path;
	// comparing this value on each frame keeps the old owner, secrets and
	// recipients from remaining under the new subject.
	subjectID string
	// balanceAccount and historyOwner are separate inputs: sharing one field
	// meant typing a history owner silently changed the account the Balance
	// card would read, under a readout fetched for someone else.
	balanceAccount string
	historyOwner   string

	info    *TokenRow
	balance string
	// Each readout is a cache keyed by the inputs that produced it. A
	// selection or create changes tokenID, and a refresh can fail; without
	// the key, rows fetched for the previous token stayed on screen under the
	// new one. The error keeps a failed same-subject refresh visible instead
	// of silently keeping stale rows.
	infoErr      error
	infoLoadedID string
	balanceErr   error
	// balanceLoadedToken/Owner identify the account the shown balance belongs
	// to, so changing either input invalidates it before the read.
	balanceLoadedToken  string
	balanceLoadedOwner  string
	historyErr          error
	historyLoadedToken  string
	historyLoadedOwner  string
	historyLoadedLimit  int
	historyLoadedOffset int

	// Write forms.
	mintTo       string
	mintAmount   string
	mintPriv     string
	xFrom        string
	xTo          string
	xAmount      string
	xPriv        string
	approveOwner string
	approveTo    string
	approveAmt   string
	approvePriv  string
	fromOwner    string
	fromTo       string
	fromAmount   string
	fromPriv     string
	// fromSpender is optional: it is not sent to the service, but lets a
	// remembered signer key be offered for Transfer From.
	fromSpender    string
	burnFrom       string
	burnAmount     string
	burnPriv       string
	allowanceOwner string
	allowanceTo    string
	historyLimit   float64
	historyOffset  float64

	allowance string
	// allowanceErr and the loaded key make an allowance readout follow the
	// token/owner/spender currently shown, like the other Token reads.
	allowanceErr         error
	allowanceLoadedToken string
	allowanceLoadedOwner string
	allowanceLoadedTo    string
	history              []TransferRow

	// tokens is the current page of stored tokens. It lets an operator pick
	// one instead of already knowing its id, while the pager reaches older
	// records without materialising the collection.
	tokens []TokenRow
	// search narrows the list by id, name or symbol while the store grows;
	// appliedSearch is the query the current highlight belongs to.
	search        string
	appliedSearch string
	// chosen is the row chosen in that list, -1 for none.
	chosen int
	// offset pages the collection. hasMore comes from requesting one row past
	// the page, so the last page never leaves a dead Next button behind.
	offset  int
	hasMore bool

	loadErr error

	// askBurn drives the irreversible-burn confirmation. The burn only runs
	// when the operator picks the destructive button, mirroring the CLI's
	// --confirm gate.
	askBurn bool
	// opTab is the operation shown in the write column. Six full forms
	// stacked in one column buried every later action below the fold; one
	// form at a time keeps the subject and the chosen operation visible.
	opTab int
	// createAdvanced and historyAdvanced hold the disclosures for fields that
	// most first uses do not need: token decimals and paging.
	createAdvanced  bool
	historyAdvanced bool

	status statusLine

	historyTable ui.ListState
	list         ui.ListState
}

const tokenPageSize = 100

// loadTokenPage commits the new page offset only after the read succeeds. A
// failed Next/Previous therefore leaves the last good rows labelled with the
// page they actually came from instead of moving the pager under them.
func (a *App) loadTokenPage(offset int) bool {
	if a.services == nil {
		return false
	}
	// The list is the page's entry point: without it a token created in an
	// earlier session could not be reached at all.
	if offset < 0 {
		offset = 0
	}
	tokens, err := a.services.ListTokens(tokenPageSize+1, offset)
	a.token.loadErr = err
	if err != nil {
		return false
	}
	if len(tokens) == 0 && offset > 0 {
		return a.loadTokenPage(0)
	}
	a.token.offset = offset
	a.token.hasMore = len(tokens) > tokenPageSize
	if a.token.hasMore {
		tokens = tokens[:tokenPageSize]
	}
	a.token.tokens = tokens
	return true
}

// tokenView lays the page out in two columns: the token you are working with
// on the left (create, inspect, history), and the operations that change it on
// the right (mint, transfer, approve, transfer-from, burn, allowance). Ten
// full-width forms stacked in one column buried every write below the fold.
func (a *App) tokenView(c *ui.Context) {
	a.syncTokenSubject()
	a.scrollPage(c, func() {
		guide(c, &a.guides.token,
			"Select a token in the left column, or create one. Its owner public key fills the account fields for you.",
			"Choose an operation on the right: Mint, Transfer, Approve, Transfer From, Burn or Allowance.",
			"Mint/Approve/Burn sign with the owner private key; Transfer with the sender's; Transfer From with the spender's. Keys are never stored, and Use generated owner key works only for the token that key created.",
		)
		twoColumns(c, func() {
			a.tokenList(c)
			a.tokenCreate(c)
			a.tokenRead(c)
			a.tokenHistory(c)
		}, func() {
			a.tokenWrites(c)
		})
		a.renderBurnDialog(c)
	})
}

// tokenList draws the stored tokens and lets the operator choose one: a
// choice fills the id every other card acts on, so a token created in an
// earlier session is reachable without remembering its id.
func (a *App) tokenList(c *ui.Context) {
	formCard(c, "Tokens", "Browse stored tokens newest first and choose one as the subject of the cards here.", func() {
		if a.token.loadErr != nil && !loadWarning(c, "Failed to load tokens", a.token.loadErr, len(a.token.tokens) > 0) {
			return
		}
		if len(a.token.tokens) == 0 {
			emptyState(c, pageToken, "No tokens yet", "Create the first token above; the list, forms and history follow it.")
			return
		}
		ui.SearchField(c, &a.token.search).Label(tr("Search tokens"))
		if a.token.search != a.token.appliedSearch {
			// The highlight indexes the filtered rows; after a new query the same
			// index is a different token, so no row is chosen until the operator
			// picks one from the list they are looking at.
			a.token.appliedSearch = a.token.search
			a.token.chosen = -1
		}
		if previous, next := listPager(c, a.token.offset, len(a.token.tokens), a.token.hasMore); previous || next {
			target := a.token.offset
			if previous {
				target = max(0, target-tokenPageSize)
			} else {
				target += tokenPageSize
			}
			if a.loadTokenPage(target) {
				a.token.chosen = -1
			}
			return
		}
		if a.token.search != "" {
			hint(c, "Search narrows the current page; use Previous/Next for older tokens.")
		}
		rows := make([]TokenRow, 0, len(a.token.tokens))
		for _, t := range a.token.tokens {
			if containsFold(a.token.search, t.ID, t.Name, t.Symbol) {
				rows = append(rows, t)
			}
		}
		if len(rows) == 0 {
			emptyNote(c, fmt.Sprintf(tr("No tokens match “%s”."), strings.TrimSpace(a.token.search)))
			return
		}
		a.token.list.Selected = &a.token.chosen
		table := ui.Table(c, &a.token.list, []ui.TableColumn{
			{Title: tr("ID"), Width: 150},
			{Title: tr("Name"), MinWidth: 120},
			{Title: tr("Symbol"), Width: 90},
			{Title: tr("Supply"), Width: 130, Align: ui.End},
		}, len(rows), func(row, col int) {
			t := rows[row]
			switch col {
			case 0:
				ui.Text(c, shortID(t.ID)).SingleLine()
			case 1:
				ui.Text(c, t.Name).SingleLine()
			case 2:
				ui.Text(c, t.Symbol)
			case 3:
				ui.Text(c, t.TotalSupply)
			}
		})
		if table.Changed() && a.token.chosen >= 0 && a.token.chosen < len(rows) {
			chosen := rows[a.token.chosen]
			a.token.tokenID = chosen.ID
			// The owner's public key is known from the record; fill the
			// accounts the write forms ask for and drop the previous token's
			// secrets and recipients.
			a.rememberTokenSubjectOwner(chosen.ID, chosen.Owner)
			a.applyTokenSubject(chosen.Owner)
			// Whatever the Inspect, Balance or History cards show belongs to the
			// previous token; re-read the open ones for the chosen token.
			a.refreshToken()
		}
	})
}

func (a *App) tokenCreate(c *ui.Context) {
	formCard(c, "Create Token", "Define supply and attach the owner key that will authorize future writes.", func() {
		field(c, "Name", &a.token.name)
		field(c, "Symbol", &a.token.symbol)
		field(c, "Total Supply", &a.token.supply)
		ui.Collapsible(c, tr("Advanced"), &a.token.createAdvanced, func() {
			ui.Field(c, tr("Decimals"), func() {
				ui.Column(c).Gap(2).Children(func() {
					ui.NumberInput(c, &a.token.decimals, 0, 127, 1)
					hint(c, "0 for a whole-unit token; 8 matches most asset conventions.")
				})
			})
		})
		fieldHint(c, "Owner (base64 public key)", "Required: the owner signs every later mint, transfer and burn.", &a.token.owner)
		ui.Row(c).Gap(8).Children(func() {
			if secondaryButton(c, "Generate key pair").Clicked() {
				a.generateTokenOwner()
			}
			if a.token.ownerPriv != "" && quietButton(c, "Dismiss key").Clicked() {
				a.token.ownerPriv = ""
			}
		})
		if a.token.ownerPriv != "" {
			copyRow(c, "Owner private key", a.token.ownerPriv, func() {
				a.token.status = okStatus("Owner private key copied.")
			})
			ui.Text(c, tr("This is the only copy of the owner key; the store keeps the public half.")).
				FontSize(textSize(c, 11)).TextColor(ui.Hex(auroraAmber))
		}
		ui.Row(c).Children(func() {
			if primaryButton(c, "Create Token").Disabled(!allSet(a.token.name, a.token.symbol, a.token.supply, a.token.owner)).Clicked() {
				a.createToken()
			}
		})
	})
}

// generateTokenOwner fills the Owner field from a fresh Ed25519 key pair and
// offers the private half for copying. Without it the window could not create
// a token without a key generator outside the app, while the CLI generates one
// when the flag is omitted.
func (a *App) generateTokenOwner() {
	pub, priv, err := a.services.GenerateKeyPair()
	if err != nil {
		a.token.status = errStatus(err)
		return
	}
	a.token.owner, a.token.ownerPriv = pub, priv
	// A newly generated pair belongs to no token yet; do not let the write
	// forms reuse it against the last token created with another key.
	a.token.ownerKeyTokenID = ""
	a.token.status = okStatus("Generated an owner key pair. Copy the private key now; it is not stored.")
}

func (a *App) createToken() {
	a.token.status = statusLine{}
	decimals := int(a.token.decimals)
	if float64(decimals) != a.token.decimals || decimals < 0 || decimals > 127 {
		a.token.status = statusLine{text: tr("Decimals must be a whole number between 0 and 127."), isErr: true}
		return
	}
	name, symbol := strings.TrimSpace(a.token.name), strings.TrimSpace(a.token.symbol)
	supply, owner := strings.TrimSpace(a.token.supply), strings.TrimSpace(a.token.owner)
	ownerPriv := a.token.ownerPriv
	a.runWrite("Creating token…", func() func() {
		t, err := a.services.CreateToken(name, symbol, supply, owner, decimals)
		return func() {
			if err != nil {
				a.token.status = errStatus(err)
				return
			}
			a.token.status = okStatus("Created %s (%s) with supply %s. Owner: %s", t.Name, t.Symbol, t.TotalSupply, t.Owner)
			a.token.tokenID = t.ID
			a.token.ownerKeyTokenID = t.ID
			// The list is the page's entry point, so a new token joins it at once;
			// the readouts that were open move to the new token with it, and the
			// account fields start from the owner instead of asking for the same
			// public key six times.
			a.rememberSuccessfulKey(t.Owner, ownerPriv)
			a.rememberTokenSubjectOwner(t.ID, t.Owner)
			a.applyTokenSubject(t.Owner)
			a.refreshTokenAt(0)
			a.selectTokenByID(t.ID)
			a.token.name, a.token.symbol, a.token.supply = "", "", ""
		}
	})
}

// applyTokenSubject points every owner-shaped field at the selected token's
// owner and clears the secrets, recipients and spenders that belonged to the
// previous subject. Public keys are safe to repeat; carrying a private key or
// an old recipient across a subject change is how an operator signs or sends
// for the wrong account.
func (a *App) applyTokenSubject(owner string) {
	a.token.mintPriv, a.token.xPriv, a.token.approvePriv = "", "", ""
	a.token.fromPriv, a.token.burnPriv = "", ""
	a.token.xTo, a.token.approveTo, a.token.fromTo, a.token.allowanceTo = "", "", "", ""
	a.token.mintTo, a.token.xFrom, a.token.approveOwner = "", "", ""
	a.token.fromOwner, a.token.burnFrom, a.token.allowanceOwner = "", "", ""
	a.token.balanceAccount, a.token.historyOwner = "", ""
	a.token.fromSpender = ""
	a.token.allowance = ""
	a.token.allowanceErr = nil
	a.token.allowanceLoadedToken, a.token.allowanceLoadedOwner, a.token.allowanceLoadedTo = "", "", ""
	a.token.subjectID = strings.TrimSpace(a.token.tokenID)
	if owner == "" {
		return
	}
	a.token.mintTo = owner
	a.token.xFrom = owner
	a.token.approveOwner = owner
	a.token.fromOwner = owner
	a.token.burnFrom = owner
	a.token.allowanceOwner = owner
	a.token.balanceAccount = owner
	a.token.historyOwner = owner
}

// syncTokenSubject reacts to a Token ID typed directly into the Inspect field.
// Row selection, creation and a successful Inspect already move the owner
// context explicitly; this covers the remaining entry path before any write
// form can be submitted with the previous token's account values.
func (a *App) syncTokenSubject() {
	id := strings.TrimSpace(a.token.tokenID)
	if a.token.subjectID == id {
		return
	}
	a.applyTokenSubject(a.selectedTokenOwner())
}

func (a *App) rememberTokenSubjectOwner(id, owner string) {
	a.token.resolvedOwnerID = strings.TrimSpace(id)
	a.token.resolvedOwner = strings.TrimSpace(owner)
}

// selectTokenByID highlights a record in the collection after a create. The
// list is newest first, so the new row is normally index 0; looking it up
// still holds if a store returns another order.
func (a *App) selectTokenByID(id string) {
	a.token.search, a.token.appliedSearch = "", ""
	a.token.chosen = -1
	for i, token := range a.token.tokens {
		if token.ID == id {
			a.token.chosen = i
			return
		}
	}
}

func (a *App) tokenRead(c *ui.Context) {
	formCard(c, "Inspect", "Read a token's metadata and an account's balance.", func() {
		a.tokenReadBody(c)
	})
}

func (a *App) tokenReadBody(c *ui.Context) {
	field(c, "Token ID", &a.token.tokenID)
	tokenID := strings.TrimSpace(a.token.tokenID)
	ui.Row(c).Children(func() {
		if secondaryButton(c, "Get Token Info").Clicked() {
			id := strings.TrimSpace(a.token.tokenID)
			a.clearTokenInfoForAnotherSubject(id)
			if err := a.loadTokenInfo(id); err != nil {
				a.token.status = errStatus(err)
			} else {
				a.token.status = statusLine{}
			}
		}
	})
	if a.token.infoErr != nil && a.token.infoLoadedID == tokenID {
		loadWarning(c, "Couldn't load token info", a.token.infoErr, a.token.info != nil)
	}
	if info := a.token.info; info != nil && a.token.infoLoadedID == tokenID {
		readout(c, []readoutRow{
			{"Name", info.Name + " (" + info.Symbol + ")"},
			{"Supply", info.TotalSupply},
			{"Decimals", strconv.Itoa(info.Decimals)},
			{"Owner", info.Owner},
		})
	}

	field(c, "Account (base64 public key)", &a.token.balanceAccount)
	account := strings.TrimSpace(a.token.balanceAccount)
	ui.Row(c).Children(func() {
		if secondaryButton(c, "Get Balance").Clicked() {
			id, owner := strings.TrimSpace(a.token.tokenID), strings.TrimSpace(a.token.balanceAccount)
			a.clearTokenBalanceForAnotherRead(id, owner)
			if err := a.loadTokenBalance(id, owner); err != nil {
				a.token.status = errStatus(err)
			} else {
				a.token.status = statusLine{}
			}
		}
	})
	balanceMatches := a.token.balanceLoadedToken == tokenID && a.token.balanceLoadedOwner == account
	if a.token.balanceErr != nil && balanceMatches {
		loadWarning(c, "Couldn't load balance", a.token.balanceErr, a.token.balance != "")
	}
	if a.token.balance != "" && balanceMatches {
		readout(c, []readoutRow{{"Balance", a.token.balance}})
	}
}

// loadTokenInfo reads a token's metadata into the Inspect card. A failure
// keeps the rows only when they were loaded for the same token; the caller
// invalidates them when the subject changes.
func (a *App) loadTokenInfo(id string) error {
	subjectChanged := a.token.resolvedOwnerID != id
	info, err := a.services.TokenInfo(id)
	if err != nil {
		a.token.infoErr = err
		a.token.infoLoadedID = id
		return err
	}
	a.token.info = &info
	a.token.infoLoadedID = id
	a.token.infoErr = nil
	a.rememberTokenSubjectOwner(id, info.Owner)
	if subjectChanged {
		// Inspect is another entry point for choosing the token every write
		// acts on. Resolving an id outside the visible page must fill the same
		// owner fields as choosing its row, while a refresh of the same subject
		// must not erase values already entered in the forms.
		a.applyTokenSubject(info.Owner)
	}
	return nil
}

func (a *App) clearTokenInfoForAnotherSubject(id string) {
	if a.token.infoLoadedID == id {
		return
	}
	a.token.info = nil
	a.token.infoErr = nil
	a.token.infoLoadedID = ""
}

// loadTokenBalance reads one account's balance for one token. Both are part of
// the key: changing either makes the shown number describe something else.
func (a *App) loadTokenBalance(tokenID, owner string) error {
	balance, err := a.services.TokenBalance(tokenID, owner)
	if err != nil {
		a.token.balanceErr = err
		a.token.balanceLoadedToken, a.token.balanceLoadedOwner = tokenID, owner
		return err
	}
	a.token.balance = balance
	a.token.balanceLoadedToken, a.token.balanceLoadedOwner = tokenID, owner
	a.token.balanceErr = nil
	return nil
}

func (a *App) clearTokenBalanceForAnotherRead(tokenID, owner string) {
	if a.token.balanceLoadedToken == tokenID && a.token.balanceLoadedOwner == owner {
		return
	}
	a.token.balance = ""
	a.token.balanceErr = nil
	a.token.balanceLoadedToken, a.token.balanceLoadedOwner = "", ""
}

// loadTokenHistory reads one page of a token's transfers. The token, owner,
// limit and offset are the key; a failure keeps the rows only when they were
// produced by that same query.
func (a *App) loadTokenHistory(tokenID, owner string, limit, offset int) error {
	rows, err := a.services.TokenHistory(tokenID, owner, limit, offset)
	if err != nil {
		a.token.historyErr = err
		a.token.historyLoadedToken, a.token.historyLoadedOwner = tokenID, owner
		a.token.historyLoadedLimit, a.token.historyLoadedOffset = limit, offset
		return err
	}
	a.token.history = rows
	a.token.historyLoadedToken, a.token.historyLoadedOwner = tokenID, owner
	a.token.historyLoadedLimit, a.token.historyLoadedOffset = limit, offset
	a.token.historyErr = nil
	return nil
}

func (a *App) clearTokenHistoryForAnotherRead(tokenID, owner string, limit, offset int) {
	if a.token.historyLoadedToken == tokenID && a.token.historyLoadedOwner == owner &&
		a.token.historyLoadedLimit == limit && a.token.historyLoadedOffset == offset {
		return
	}
	a.token.history = nil
	a.token.historyErr = nil
	a.token.historyLoadedToken, a.token.historyLoadedOwner = "", ""
}

// readoutRow is one label/value pair in a readout.
type readoutRow struct{ label, value string }

// readout draws the result of a read as label/value rows on a recessed panel,
// so an answer is visibly an answer rather than another line of prose that
// looks like the hint above it.
func readout(c *ui.Context, rows []readoutRow) {
	ui.Column(c).FillWidth().Padding(10).Gap(4).Radius(8).
		Background(ui.Hex(night)).Children(func() {
		for _, r := range rows {
			ui.Row(c).Gap(8).Children(func() {
				ui.Text(c, tr(r.label)).FontSize(textSize(c, 11)).Width(72).TextColor(ui.Hex(inkMuted))
				ui.Text(c, r.value).FontSize(textSize(c, 12)).TextColor(ui.Hex(ink)).SingleLine()
			})
		}
	})
}

// useOwnerKeyButton offers the private key generated by the Create card to a
// form that must sign as the token owner. It is shown only while that key's
// token is the current subject and (for Transfer) the entered sender is the
// owner; otherwise it would sign for the wrong account.
func (a *App) useOwnerKeyButton(c *ui.Context, target *string, allow bool) {
	if !allow || a.token.ownerPriv == "" || a.token.ownerKeyTokenID == "" ||
		a.token.ownerKeyTokenID != strings.TrimSpace(a.token.tokenID) {
		return
	}
	if quietButton(c, "Use generated owner key").Clicked() {
		*target = a.token.ownerPriv
	}
}

// selectedTokenOwner is the owner of the token the page is acting on, or "".
func (a *App) selectedTokenOwner() string {
	id := strings.TrimSpace(a.token.tokenID)
	if id != "" && a.token.resolvedOwnerID == id {
		return a.token.resolvedOwner
	}
	if id != "" && a.token.info != nil && a.token.infoLoadedID == id {
		return a.token.info.Owner
	}
	for _, token := range a.token.tokens {
		if token.ID == id {
			return token.Owner
		}
	}
	return ""
}

// tokenSubject names the token every write on this page acts on.
//
// The cards take no token id of their own: they all use a.token.tokenID, which
// Create and Inspect set. Without saying so, the right-hand column gave no
// sign of which token a Mint would hit — the one thing an operator must be
// sure of before a write.
func tokenSubject(c *ui.Context, id string) {
	if id == "" {
		ui.Row(c).FillWidth().Gap(10).AlignItems(ui.Center).Padding(10).Radius(8).
			Background(ui.Hex(warningTint)).BorderWidth(1).BorderColor(ui.Hex(auroraAmber)).
			Children(func() {
				badge(c, "No token selected", auroraAmber, night)
				ui.Text(c, tr("Create or inspect one first.")).FontSize(textSize(c, 12)).TextColor(ui.Hex(ink))
			})
		return
	}
	ui.Row(c).FillWidth().Gap(10).AlignItems(ui.Center).Padding(10).Radius(8).
		Background(ui.Hex(night)).Children(func() {
		ui.Text(c, tr("Acting on")).FontSize(textSize(c, 11)).TextColor(ui.Hex(inkMuted))
		ui.Text(c, id).FontSize(textSize(c, 13)).Bold().TextColor(ui.Hex(aurora)).SingleLine()
		if quietButton(c, "Copy token ID").Clicked() {
			c.Services().WriteClipboard(id)
			c.Toast(tr("Token ID is on the clipboard"))
		}
	})
}

func (a *App) tokenWrites(c *ui.Context) {
	tokenSubject(c, a.token.tokenID)
	ui.Tabs(c, &a.token.opTab, tr("Mint"), tr("Transfer"), tr("Approve"), tr("Transfer From"), tr("Burn"), tr("Allowance"))
	switch a.token.opTab {
	case 0:
		formCard(c, "Mint", "Only the token owner can mint, and only for a mintable token.", func() {
			field(c, "To (base64 public key)", &a.token.mintTo)
			field(c, "Amount", &a.token.mintAmount)
			field(c, "Owner Private Key", &a.token.mintPriv)
			a.useOwnerKeyButton(c, &a.token.mintPriv, true)
			a.useSavedKeyButton(c, a.selectedTokenOwner(), &a.token.mintPriv)
			ui.Row(c).Children(func() {
				if primaryButton(c, "Mint").Disabled(!allSet(a.token.tokenID, a.token.mintTo, a.token.mintAmount, a.token.mintPriv)).Clicked() {
					a.mintToken()
				}
			})
		})

	case 1:
		formCard(c, "Transfer", "Move tokens from one account to another.", func() {
			field(c, "From (base64 public key)", &a.token.xFrom)
			field(c, "To (base64 public key)", &a.token.xTo)
			field(c, "Amount", &a.token.xAmount)
			field(c, "From Private Key", &a.token.xPriv)
			a.useOwnerKeyButton(c, &a.token.xPriv,
				strings.TrimSpace(a.token.xFrom) == a.selectedTokenOwner())
			a.useSavedKeyButton(c, a.token.xFrom, &a.token.xPriv)
			ui.Row(c).Children(func() {
				if primaryButton(c, "Transfer").Disabled(!allSet(a.token.tokenID, a.token.xFrom, a.token.xTo, a.token.xAmount, a.token.xPriv)).Clicked() {
					a.transferToken()
				}
			})
		})

	case 2:
		formCard(c, "Approve", "Let a spender move up to an amount on the owner's behalf.", func() {
			field(c, "Owner (base64 public key)", &a.token.approveOwner)
			field(c, "Spender (base64 public key)", &a.token.approveTo)
			field(c, "Amount", &a.token.approveAmt)
			field(c, "Owner Private Key", &a.token.approvePriv)
			a.useOwnerKeyButton(c, &a.token.approvePriv,
				strings.TrimSpace(a.token.approveOwner) == a.selectedTokenOwner())
			a.useSavedKeyButton(c, a.token.approveOwner, &a.token.approvePriv)
			ui.Row(c).Children(func() {
				if primaryButton(c, "Approve").Disabled(!allSet(a.token.tokenID, a.token.approveOwner, a.token.approveTo, a.token.approveAmt, a.token.approvePriv)).Clicked() {
					a.approveToken()
				}
			})
		})

	case 3:
		formCard(c, "Transfer From", "Spend an allowance the owner granted.", func() {
			field(c, "Owner (base64 public key)", &a.token.fromOwner)
			field(c, "To (base64 public key)", &a.token.fromTo)
			field(c, "Amount", &a.token.fromAmount)
			fieldHint(c, "Spender public key (optional)", "Used only to find a key saved for this session.", &a.token.fromSpender)
			field(c, "Spender Private Key", &a.token.fromPriv)
			a.useSavedKeyButton(c, a.token.fromSpender, &a.token.fromPriv)
			ui.Row(c).Children(func() {
				if primaryButton(c, "Transfer From").Disabled(!allSet(a.token.tokenID, a.token.fromOwner, a.token.fromTo, a.token.fromAmount, a.token.fromPriv)).Clicked() {
					a.transferFromToken()
				}
			})
		})

	case 4:
		formCard(c, "Burn", "Destroy tokens from an account. This cannot be undone.", func() {
			field(c, "From (base64 public key)", &a.token.burnFrom)
			field(c, "Amount", &a.token.burnAmount)
			field(c, "Owner Private Key", &a.token.burnPriv)
			a.useOwnerKeyButton(c, &a.token.burnPriv,
				strings.TrimSpace(a.token.burnFrom) == a.selectedTokenOwner())
			a.useSavedKeyButton(c, a.token.burnFrom, &a.token.burnPriv)
			ui.Row(c).Children(func() {
				// A destructive action carries the danger style, and the
				// confirmation still stands between it and the write.
				if dangerButton(c, "Burn…").Clicked() {
					a.token.askBurn = true
				}
			})
		})

	case 5:
		formCard(c, "Allowance", "Read how much a spender may still move.", func() {
			field(c, "Owner (base64 public key)", &a.token.allowanceOwner)
			field(c, "Spender (base64 public key)", &a.token.allowanceTo)
			ui.Row(c).Children(func() {
				if secondaryButton(c, "Get Allowance").Clicked() {
					a.loadAllowance()
				}
			})
			matches := a.token.allowanceMatches(
				strings.TrimSpace(a.token.tokenID),
				strings.TrimSpace(a.token.allowanceOwner),
				strings.TrimSpace(a.token.allowanceTo),
			)
			if a.token.allowanceErr != nil && matches &&
				!loadWarning(c, "Couldn't load allowance", a.token.allowanceErr, a.token.allowance != "") {
				return
			}
			if a.token.allowance != "" && matches {
				readout(c, []readoutRow{{"Allowance", a.token.allowance}})
			}
		})
	}
}

// The write handlers below read only the inputs of the section that invoked
// them. Sharing one address field between sections (as the page once did for
// Approve and Allowance) signs for an account the operator typed somewhere
// else and cannot see from the form they used.

func (a *App) mintToken() {
	privateKey := strings.TrimSpace(a.token.mintPriv)
	tokenID, to := strings.TrimSpace(a.token.tokenID), strings.TrimSpace(a.token.mintTo)
	amount := strings.TrimSpace(a.token.mintAmount)
	owner := a.selectedTokenOwner()
	a.runWrite("Minting…", func() func() {
		err := a.services.MintToken(tokenID, to, amount, privateKey)
		return func() {
			a.token.status = wrapErr(err)
			if err == nil {
				a.rememberSuccessfulKey(owner, privateKey)
				// A signing key that was used successfully is not kept on screen:
				// the next write needs its own key, and a shared display should not
				// retain the secret.
				a.token.mintPriv = ""
				a.refreshToken()
			}
		}
	})
}

func (a *App) transferToken() {
	privateKey := strings.TrimSpace(a.token.xPriv)
	tokenID := strings.TrimSpace(a.token.tokenID)
	from, to := strings.TrimSpace(a.token.xFrom), strings.TrimSpace(a.token.xTo)
	amount := strings.TrimSpace(a.token.xAmount)
	a.runWrite("Transferring…", func() func() {
		err := a.services.TransferToken(tokenID, from, to, amount, privateKey)
		return func() {
			a.token.status = wrapErr(err)
			if err == nil {
				a.rememberSuccessfulKey(from, privateKey)
				a.token.xPriv = ""
				a.refreshToken()
			}
		}
	})
}

func (a *App) approveToken() {
	privateKey := strings.TrimSpace(a.token.approvePriv)
	tokenID := strings.TrimSpace(a.token.tokenID)
	owner, spender := strings.TrimSpace(a.token.approveOwner), strings.TrimSpace(a.token.approveTo)
	amount := strings.TrimSpace(a.token.approveAmt)
	a.runWrite("Approving…", func() func() {
		err := a.services.ApproveToken(tokenID, owner, spender, amount, privateKey)
		return func() {
			a.token.status = wrapErr(err)
			if err == nil {
				a.rememberSuccessfulKey(owner, privateKey)
				a.token.approvePriv = ""
				a.refreshToken()
			}
		}
	})
}

func (a *App) transferFromToken() {
	privateKey := strings.TrimSpace(a.token.fromPriv)
	tokenID := strings.TrimSpace(a.token.tokenID)
	owner, to := strings.TrimSpace(a.token.fromOwner), strings.TrimSpace(a.token.fromTo)
	amount := strings.TrimSpace(a.token.fromAmount)
	spender := a.token.fromSpender
	a.runWrite("Transferring…", func() func() {
		err := a.services.TransferFromToken(tokenID, owner, to, amount, privateKey)
		return func() {
			a.token.status = wrapErr(err)
			if err == nil {
				a.rememberSuccessfulKey(spender, privateKey)
				a.token.fromPriv = ""
				a.refreshToken()
			}
		}
	})
}

// refreshToken re-reads everything the page shows: the collection (whose rows
// show total supply), an open Inspect readout, a shown balance and a loaded
// history. A write or the Refresh button must not leave stale numbers beside
// a successful result.
func (a *App) refreshToken() {
	a.refreshTokenAt(a.token.offset)
}

// refreshTokenAt re-reads the collection at offset and everything else the
// page shows. A create uses offset zero without moving the pager ahead of a
// failed list read.
func (a *App) refreshTokenAt(offset int) {
	a.loadTokenPage(offset)
	id := strings.TrimSpace(a.token.tokenID)

	// A readout is open if it holds rows or a failure from the last attempt.
	// Re-read it for the current subject; invalidate it first when the subject
	// or query changed, so a failed read cannot leave the previous answer on
	// screen under the new input.
	if a.token.info != nil || a.token.infoLoadedID != "" || a.token.infoErr != nil {
		a.clearTokenInfoForAnotherSubject(id)
		_ = a.loadTokenInfo(id)
	}
	if a.token.balance != "" || a.token.balanceLoadedToken != "" ||
		a.token.balanceLoadedOwner != "" || a.token.balanceErr != nil {
		owner := strings.TrimSpace(a.token.balanceAccount)
		a.clearTokenBalanceForAnotherRead(id, owner)
		_ = a.loadTokenBalance(id, owner)
	}
	if len(a.token.history) > 0 || a.token.historyLoadedToken != "" ||
		a.token.historyLoadedOwner != "" || a.token.historyErr != nil {
		limit, offset := a.tokenHistoryWindow()
		owner := strings.TrimSpace(a.token.historyOwner)
		a.clearTokenHistoryForAnotherRead(id, owner, limit, offset)
		_ = a.loadTokenHistory(id, owner, limit, offset)
	}
	if a.token.allowanceLoadedToken != "" || a.token.allowanceErr != nil {
		owner := strings.TrimSpace(a.token.allowanceOwner)
		spender := strings.TrimSpace(a.token.allowanceTo)
		a.clearAllowanceForAnotherRead(id, owner, spender)
		_ = a.loadTokenAllowance(id, owner, spender)
	}
}

// tokenHistoryWindow is the page size and offset the History card sends: the
// defaults the form shows, clamped to the REST surface's ceiling.
func (a *App) tokenHistoryWindow() (limit, offset int) {
	limit = int(a.token.historyLimit)
	if limit < 1 {
		limit = 50
	}
	if limit > maxListLimit {
		limit = maxListLimit
	}
	offset = int(a.token.historyOffset)
	if offset < 0 {
		offset = 0
	}
	if offset > maxListLimit {
		offset = maxListLimit
	}
	return limit, offset
}

func (a *App) loadAllowance() {
	tokenID := strings.TrimSpace(a.token.tokenID)
	owner := strings.TrimSpace(a.token.allowanceOwner)
	spender := strings.TrimSpace(a.token.allowanceTo)
	a.clearAllowanceForAnotherRead(tokenID, owner, spender)
	if err := a.loadTokenAllowance(tokenID, owner, spender); err != nil {
		a.token.status = errStatus(err)
		return
	}
	a.token.status = statusLine{}
}

func (a *App) loadTokenAllowance(tokenID, owner, spender string) error {
	amount, err := a.services.TokenAllowance(tokenID, owner, spender)
	a.token.allowanceLoadedToken = tokenID
	a.token.allowanceLoadedOwner = owner
	a.token.allowanceLoadedTo = spender
	if err != nil {
		a.token.allowanceErr = err
		return err
	}
	a.token.allowance = amount
	a.token.allowanceErr = nil
	return nil
}

func (a *App) clearAllowanceForAnotherRead(tokenID, owner, spender string) {
	if a.token.allowanceMatches(tokenID, owner, spender) {
		return
	}
	a.token.allowance = ""
	a.token.allowanceErr = nil
	a.token.allowanceLoadedToken = ""
	a.token.allowanceLoadedOwner = ""
	a.token.allowanceLoadedTo = ""
}

func (s tokenState) allowanceMatches(tokenID, owner, spender string) bool {
	return s.allowanceLoadedToken == tokenID &&
		s.allowanceLoadedOwner == owner &&
		s.allowanceLoadedTo == spender
}

// renderBurnDialog shows the confirmation while a burn is pending. MyGo draws
// it over the window; the burn runs only when the operator picks "Burn", the
// same gate the CLI's --confirm flag is.
func (a *App) renderBurnDialog(c *ui.Context) {
	if !a.token.askBurn {
		return
	}
	// Name the amount and the account in the question: a bare "Burn tokens?"
	// asked the operator to trust whichever fields the form held, and a wrong
	// amount is irreversible.
	detail := tr("Burning destroys the amount permanently. This cannot be undone.")
	amount := strings.TrimSpace(a.token.burnAmount)
	from := strings.TrimSpace(a.token.burnFrom)
	if amount != "" || from != "" {
		detail = fmt.Sprintf(
			"Burn %s from %s? The tokens are destroyed permanently and cannot be recovered.",
			valueOr(amount), valueOr(from))
	}
	switch ui.AlertDialog(c, &a.token.askBurn, tr("Burn tokens?"), detail, tr("Cancel"), tr("Burn")) {
	case 1:
		privateKey := strings.TrimSpace(a.token.burnPriv)
		tokenID := strings.TrimSpace(a.token.tokenID)
		owner := a.token.burnFrom
		a.runWrite("Burning…", func() func() {
			err := a.services.BurnToken(tokenID, from, amount, privateKey)
			return func() {
				a.token.status = wrapErr(err)
				if err == nil {
					a.rememberSuccessfulKey(owner, privateKey)
					a.token.burnPriv = ""
					a.refreshToken()
				}
			}
		})
	}
}

func (a *App) tokenHistory(c *ui.Context) {
	formCard(c, "History", "Transfers this account sent or received.", func() {
		a.tokenHistoryBody(c)
	})
}

func (a *App) tokenHistoryBody(c *ui.Context) {
	fieldHint(c, "Owner (base64 public key)", "Leave empty to page the token's whole transfer stream.", &a.token.historyOwner)
	ui.Collapsible(c, tr("Paging"), &a.token.historyAdvanced, func() {
		ui.Row(c).Gap(12).Children(func() {
			ui.Field(c, tr("Limit"), func() {
				ui.NumberInput(c, &a.token.historyLimit, 1, maxListLimit, 1)
			})
			ui.Field(c, tr("Offset"), func() {
				ui.NumberInput(c, &a.token.historyOffset, 0, maxListLimit, 1)
			})
		})
	})
	ui.Row(c).Children(func() {
		if secondaryButton(c, "Load History").Clicked() {
			id := strings.TrimSpace(a.token.tokenID)
			owner := strings.TrimSpace(a.token.historyOwner)
			limit, offset := a.tokenHistoryWindow()
			a.clearTokenHistoryForAnotherRead(id, owner, limit, offset)
			if err := a.loadTokenHistory(id, owner, limit, offset); err != nil {
				a.token.status = errStatus(err)
			} else {
				a.token.status = statusLine{}
			}
		}
	})
	id := strings.TrimSpace(a.token.tokenID)
	owner := strings.TrimSpace(a.token.historyOwner)
	limit, offset := a.tokenHistoryWindow()
	matches := a.token.historyLoadedToken == id && a.token.historyLoadedOwner == owner &&
		a.token.historyLoadedLimit == limit && a.token.historyLoadedOffset == offset
	if a.token.historyErr != nil && matches &&
		!loadWarning(c, "Couldn't load history", a.token.historyErr, len(a.token.history) > 0) {
		return
	}
	if !matches || len(a.token.history) == 0 {
		emptyNote(c, "No transfers loaded yet.")
		return
	}
	hist := a.token.history
	ui.Table(c, &a.token.historyTable, []ui.TableColumn{
		{Title: tr("From"), Width: 160},
		{Title: tr("To"), Width: 160},
		{Title: tr("Amount"), Width: 100, Align: ui.End},
		{Title: tr("Nonce"), Width: 80, Align: ui.End},
	}, len(hist), func(row, col int) {
		h := hist[row]
		switch col {
		case 0:
			ui.Text(c, h.From).SingleLine()
		case 1:
			ui.Text(c, h.To).SingleLine()
		case 2:
			ui.Text(c, h.Amount)
		case 3:
			ui.Text(c, strconv.FormatUint(h.Nonce, 10))
		}
	})
}

// wrapErr turns a service call's error into the page's status line, and a nil
// error into a success line.
func wrapErr(err error) statusLine {
	if err != nil {
		return errStatus(err)
	}
	return okStatus("Done.")
}
